Design:
{
 "context": "payments",
 "base_package": "com.bank.payments",
 "entities": [
  {
   "name": "PaymentOrder",
   "table": "payment_orders",
   "legacy_table": "ORDENES",
   "key": [
    "orderNumber",
    "companyId"
   ],
   "fields": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": "order_number",
     "legacy": "ORD_NUMERO"
    },
    {
     "name": "companyId",
     "type": "integer(32,signed)",
     "column": "company_id",
     "legacy": "ORD_EMPRESA"
    },
    {
     "name": "status",
     "type": "text(fixed,1,iso8859-1)",
     "column": "status",
     "legacy": "ORD_ESTADO"
    },
    {
     "name": "value",
     "type": "decimal(11,2,signed)",
     "column": "order_value",
     "legacy": "ORD_VALOR"
    },
    {
     "name": "movementNumber",
     "type": "integer(64,signed)",
     "column": "movement_number",
     "legacy": "ORD_MOVIM"
    },
    {
     "name": "commission",
     "type": "decimal(5,2,signed)",
     "column": "commission",
     "legacy": "ORD_COMIS"
    }
   ]
  },
  {
   "name": "Account",
   "table": "customer_accounts",
   "legacy_table": "CUENTAS",
   "key": [
    "accountNumber"
   ],
   "fields": [
    {
     "name": "accountNumber",
     "type": "integer(64,signed)",
     "column": "account_number",
     "legacy": "CTA_NUMERO"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": "account_type",
     "legacy": "CTA_TIPO"
    },
    {
     "name": "balance",
     "type": "decimal(13,2,signed)",
     "column": "balance",
     "legacy": "CTA_SALDO"
    },
    {
     "name": "status",
     "type": "text(fixed,1,iso8859-1)",
     "column": "status",
     "legacy": "CTA_ESTADO"
    }
   ]
  }
 ],
 "ports": [
  {
   "name": "OrderRepository",
   "entity": "PaymentOrder",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByKey",
     "description": "Reads the order by company and order number locking the row for update (READ ORDENES UPDATE).",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_NUMERO"
      },
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_EMPRESA"
      }
     ],
     "returns": "PaymentOrder",
     "legacy_output": null
    },
    {
     "name": "markPaid",
     "description": "Sets the order to paid ('G') and stores the movement number and the commission charged (REWRITE ORDENES).",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_NUMERO"
      },
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_EMPRESA"
      },
      {
       "name": "movementNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "ORD_MOVIM"
      },
      {
       "name": "commission",
       "type": "decimal(5,2,signed)",
       "column": null,
       "legacy": "ORD_COMIS"
      }
     ],
     "returns": "int",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "AccountRepository",
   "entity": "Account",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByNumber",
     "description": "Reads the account by number locking the row for update (READ CUENTAS UPDATE).",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "CTA_NUMERO"
      }
     ],
     "returns": "Account",
     "legacy_output": null
    },
    {
     "name": "updateBalance",
     "description": "Rewrites the balance of the account (REWRITE CUENTAS).",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "CTA_NUMERO"
      },
      {
       "name": "balance",
       "type": "decimal(13,2,signed)",
       "column": null,
       "legacy": "CTA_SALDO"
      }
     ],
     "returns": "int",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "MovementGateway",
   "entity": null,
   "legacy_program": "PAGOMOV",
   "methods": [
    {
     "name": "registerMovement",
     "description": "Registers the movement of the paid order and returns the movement number (LINK PAGOMOV).",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "MOV_ORDEN"
      }
     ],
     "returns": "long",
     "legacy_output": "MOV_NUMERO"
    }
   ]
  }
 ],
 "use_cases": [
  {
   "name": "DebitAccount",
   "description": "Debits the customer account (PAGODEB). Validates existence, type, status and balance and answers with a response code as data: 00 debited, 10 inactive, 20 insufficient funds, 30 not found, 40 type mismatch. Called in process by PayOrder inside its transaction and also exposed on its own.",
   "rules": [
    "RULE-001",
    "RULE-002",
    "RULE-003",
    "RULE-004",
    "RULE-005"
   ],
   "inputs": [
    {
     "name": "accountNumber",
     "type": "integer(64,signed)",
     "column": null,
     "legacy": "DEB-CUENTA"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "DEB-TIPO"
    },
    {
     "name": "amount",
     "type": "decimal(13,2,signed)",
     "column": null,
     "legacy": "DEB-MONTO"
    }
   ],
   "outputs": [
    {
     "name": "responseCode",
     "type": "text(fixed,2,iso8859-1)",
     "column": null,
     "legacy": "DEB-RESP"
    },
    {
     "name": "balance",
     "type": "decimal(13,2,signed)",
     "column": null,
     "legacy": "CTA-SALDO"
    }
   ],
   "errors": [],
   "ports": [
    "AccountRepository"
   ],
   "http_method": "POST",
   "path": "/accounts/debits",
   "legacy_program": "PAGODEB",
   "unit_of_work": null,
   "legacy_message": null
  },
  {
   "name": "PayOrder",
   "description": "Pays an order (PAGOORD, transaction PGOR): validates the input, reads the pending order, checks the amount, calculates the commission, debits the account through DebitAccount, registers the movement through PAGOMOV and marks the order paid. Any rejection happens before any change is committed and answers with a business error.",
   "rules": [
    "RULE-007",
    "RULE-008",
    "RULE-009",
    "RULE-010",
    "RULE-011",
    "RULE-012",
    "RULE-013",
    "RULE-014",
    "RULE-015"
   ],
   "inputs": [
    {
     "name": "orderNumber",
     "type": "text(fixed,7,iso8859-1)",
     "column": null,
     "legacy": "ORDEN"
    },
    {
     "name": "companyId",
     "type": "text(fixed,5,iso8859-1)",
     "column": null,
     "legacy": "EMPRESA"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "TIPCTA"
    },
    {
     "name": "accountNumber",
     "type": "text(fixed,10,iso8859-1)",
     "column": null,
     "legacy": "CUENTA"
    },
    {
     "name": "amount",
     "type": "decimal(11,2,signed)",
     "column": null,
     "legacy": "VALOR"
    },
    {
     "name": "channel",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "CANAL"
    },
    {
     "name": "approvalKey",
     "type": "text(fixed,6,iso8859-1)",
     "column": null,
     "legacy": "CLAVE"
    }
   ],
   "outputs": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "RORDEN"
    },
    {
     "name": "commission",
     "type": "decimal(5,2,signed)",
     "column": null,
     "legacy": "RCOMIS"
    },
    {
     "name": "movementNumber",
     "type": "integer(64,signed)",
     "column": null,
     "legacy": "RMOVIM"
    },
    {
     "name": "resultMessage",
     "type": "text(var,40,iso8859-1)",
     "column": null,
     "legacy": "RMENS"
    }
   ],
   "errors": [
    {
     "code": "INVALID_ORDER_NUMBER",
     "legacy_code": "-1",
     "message": "NUMERO DE ORDEN INVALIDO"
    },
    {
     "code": "ACCOUNT_TYPE_NOT_ALLOWED",
     "legacy_code": "-1",
     "message": "TIPO DE CUENTA NO PERMITIDO"
    },
    {
     "code": "CHANNEL_NOT_ALLOWED",
     "legacy_code": "-1",
     "message": "CANAL NO PERMITIDO"
    },
    {
     "code": "APPROVAL_KEY_REQUIRED",
     "legacy_code": "-1",
     "message": "CLAVE DE APROBACION REQUERIDA"
    },
    {
     "code": "ORDER_NOT_FOUND",
     "legacy_code": "-1",
     "message": "ORDEN NO EXISTE"
    },
    {
     "code": "ORDER_NOT_PENDING",
     "legacy_code": "-1",
     "message": "ORDEN NO ESTA PENDIENTE"
    },
    {
     "code": "AMOUNT_MISMATCH",
     "legacy_code": "-1",
     "message": "VALOR NO COINCIDE CON LA ORDEN"
    },
    {
     "code": "ACCOUNT_INACTIVE",
     "legacy_code": "-1",
     "message": "CUENTA INACTIVA"
    },
    {
     "code": "INSUFFICIENT_FUNDS",
     "legacy_code": "-1",
     "message": "SALDO INSUFICIENTE"
    },
    {
     "code": "INVALID_ACCOUNT",
     "legacy_code": "-1",
     "message": "CUENTA NO VALIDA"
    }
   ],
   "ports": [
    "OrderRepository",
    "AccountRepository",
    "MovementGateway"
   ],
   "http_method": "POST",
   "path": "/payments/orders",
   "legacy_program": "PAGOORD",
   "unit_of_work": {
    "begins_at": 37,
    "commits_at": 172,
    "savepoints": [],
    "rollbacks": []
   },
   "legacy_message": "MENSAJE"
  },
  {
   "name": "SelectMenuOption",
   "description": "Routes the option chosen on the payments menu (PAGOMNU): '1' goes to order payment, '9' ends the session, any other option is rejected with 'OPCION NO VALIDA'.",
   "rules": [
    "RULE-006"
   ],
   "inputs": [
    {
     "name": "option",
     "type": "text(fixed,1,iso8859-1)",
     "column": null,
     "legacy": "OPCIONI"
    }
   ],
   "outputs": [
    {
     "name": "destination",
     "type": "text(var,8,iso8859-1)",
     "column": null,
     "legacy": "PROGRAM"
    }
   ],
   "errors": [
    {
     "code": "INVALID_OPTION",
     "legacy_code": "-1",
     "message": "OPCION NO VALIDA"
    }
   ],
   "ports": [],
   "http_method": "POST",
   "path": "/payments/menu",
   "legacy_program": "PAGOMNU",
   "unit_of_work": null,
   "legacy_message": "MENSAJEO"
  }
 ],
 "decisions": [
  {
   "title": "Data migrates to the target database",
   "context": "ORDENES and CUENTAS are VSAM KSDS files; the project's target is PostgreSQL.",
   "decision": "Both files become tables payment_orders and customer_accounts with the same key and the same numeric precision (decimal(11,2), decimal(13,2), decimal(5,2)). The FILLER of the order record is not migrated.",
   "consequences": "Data must be loaded once from the VSAM files. Keys are numeric columns: 7 and 5 digits for the order, 10 digits (long) for the account and the movement."
  },
  {
   "title": "Transaction owned by the REST adapter",
   "context": "PAGOORD works in one unit of work (begin at line 37, SYNCPOINT at line 172). Every rejection happens before any write is confirmed and returns a non-zero status with only the message.",
   "decision": "The REST adapter opens the transaction and commits at the end of PayOrder. A business error rolls everything back. The service does not call begin/commit/rollback itself, and there are no savepoints. The READ ... UPDATE of the legacy becomes SELECT ... FOR UPDATE on the order and the account.",
   "consequences": "In the target the debit and the order update are atomic. If PAGOMOV fails, the debit is undone, which the CICS program could not guarantee."
  },
  {
   "title": "PAGODEB becomes an in-process use case",
   "context": "PAGODEB is part of the migrated data domain. Its rules are in the approved set and its effect on CUENTAS is part of the golden master. PAGOORD LINKs to it.",
   "decision": "PAGODEB is the use case DebitAccount, which PayOrder invokes in the same transaction instead of a LINK. Its response codes (00/10/20/30/40) stay as data (DEB-RESP) and are not business errors. PayOrder maps them as the legacy does: 10 -> ACCOUNT_INACTIVE, 20 -> INSUFFICIENT_FUNDS, anything else -> INVALID_ACCOUNT.",
   "consequences": "No generated adapter is needed for PAGODEB. Rules 001-005 are implemented once."
  },
  {
   "title": "PAGOMOV is a port",
   "context": "PAGOMOV is not in the inputs and is called with LINK. The traces stub it with MOV_NUMERO.",
   "decision": "MovementGateway replaces PAGOMOV (legacy_program PAGOMOV, output MOV_NUMERO). It will be stubbed until its source is available.",
   "consequences": "The real behaviour of PAGOMOV is not covered by the golden master."
  },
  {
   "title": "Amount arrives as a decimal",
   "context": "The legacy reads VALORI as a screen string converted with NUMVAL(VALORI)/100, but the traces carry the amount as a decimal ('1500.00') and compare it directly with the order value.",
   "decision": "PayOrder receives the amount as decimal(11,2) and compares it with the order value by value (scale 2).",
   "consequences": "The screen string conversion is a UI concern and is not translated."
  },
  {
   "title": "Screens, keys and commarea are not translated",
   "context": "BMS maps, PF3/ENTER/other keys, the 13-byte commarea (CA-ULTIMA-ORDEN, CA-EMPRESA) and the pseudo-conversational RETURN TRANSID are CICS plumbing.",
   "decision": "REST endpoints replace the maps and key handling. The result of a payment is the response body. The menu use case only returns the destination. The last order in the commarea is not kept in the server.",
   "consequences": "A client that needs the last order must keep it itself."
  }
 ],
 "masks": [],
 "infrastructure": [],
 "data_strategy": "migration"
}

Use case: PayOrder

Rules:
[
 {
  "id": "RULE-007",
  "name": "Order number must be numeric and non-zero",
  "category": "validation",
  "priority": "P1",
  "statement": "When the order number ORDENI is not numeric or equals zeros, the message 'NUMERO DE ORDEN INVALIDO' is set in WS-MENSAJE and the HAY-ERROR flag is set.",
  "condition": "ORDENI NOT NUMERIC OR ORDENI = ZEROS",
  "action": "Set message 'NUMERO DE ORDEN INVALIDO' and flag the request as in error. No order is read and no debit is made.",
  "inputs": [
   {
    "name": "ORDENI",
    "type": "text(fixed,7,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Order number is zero\n Given the order number entered is 0000000\n When the user presses ENTER\n Then the message 'NUMERO DE ORDEN INVALIDO' is shown and the payment is not processed",
   "Scenario: Order number contains letters\n Given the order number entered is 12A4567\n When the user presses ENTER\n Then the message 'NUMERO DE ORDEN INVALIDO' is shown"
  ],
  "sources": [
   {
    "file": "cbl/PAGOORD.cbl",
    "line_start": 83,
    "line_end": 85
   }
  ]
 },
 {
  "id": "RULE-008",
  "name": "Allowed account types for order payment",
  "category": "validation",
  "priority": "P0",
  "statement": "Only account types CTE, AHO and VIR may be used to pay an order. Any other type is rejected with 'TIPO DE CUENTA NO PERMITIDO'.",
  "condition": "TIPCTAI NOT IN ('CTE','AHO','VIR')",
  "action": "Set message 'TIPO DE CUENTA NO PERMITIDO' and flag the request as in error.",
  "inputs": [
   {
    "name": "TIPCTAI",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Savings account accepted\n Given a valid order number and account type AHO\n When the request is validated\n Then the account type check passes",
   "Scenario: Unknown account type\n Given a valid order number and account type XYZ\n When the request is validated\n Then the message 'TIPO DE CUENTA NO PERMITIDO' is shown"
  ],
  "sources": [
   {
    "file": "cbl/PAGOORD.cbl",
    "line_start": 87,
    "line_end": 90
   }
  ]
 },
 {
  "id": "RULE-009",
  "name": "Allowed channels for order payment",
  "category": "validation",
  "priority": "P1",
  "statement": "The payment channel must be WEB or OFI. Any other channel is rejected with 'CANAL NO PERMITIDO'.",
  "condition": "CANALI NOT IN ('WEB','OFI')",
  "action": "Set message 'CANAL NO PERMITIDO' and flag the request as in error.",
  "inputs": [
   {
    "name": "CANALI",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Invalid channel\n Given a valid order number, account type CTE and channel ATM\n When the request is validated\n Then the message 'CANAL NO PERMITIDO' is shown",
   "Scenario: Valid channel\n Given channel WEB\n When the request is validated\n Then the channel check passes"
  ],
  "sources": [
   {
    "file": "cbl/PAGOORD.cbl",
    "line_start": 92,
    "line_end": 94
   }
  ]
 },
 {
  "id": "RULE-010",
  "name": "Office channel requires approval key",
  "category": "validation",
  "priority": "P1",
  "statement": "A payment through the office channel (OFI) must carry an approval key. If the key is blank the request is rejected with 'CLAVE DE APROBACION REQUERIDA'.",
  "condition": "CANALI = 'OFI' AND CLAVEI = SPACES",
  "action": "Set message 'CLAVE DE APROBACION REQUERIDA' and flag the request as in error.",
  "inputs": [
   {
    "name": "CANALI",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   },
   {
    "name": "CLAVEI",
    "type": "text(fixed,6,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: OFI without key\n Given channel OFI and a blank approval key\n When the request is validated\n Then the message 'CLAVE DE APROBACION REQUERIDA' is shown",
   "Scenario: WEB without key\n Given channel WEB and a blank approval key\n When the request is validated\n Then no error is raised for the key"
  ],
  "sources": [
   {
    "file": "cbl/PAGOORD.cbl",
    "line_start": 96,
    "line_end": 99
   }
  ]
 },
 {
  "id": "RULE-011",
  "name": "Order must exist and be pending",
  "category": "validation",
  "priority": "P0",
  "statement": "The order, identified by company and order number, must exist and be in pending status to be paid. Otherwise the payment is rejected with 'ORDEN NO EXISTE' or 'ORDEN NO ESTA PENDIENTE'.",
  "condition": "READ of ORDENES by (EMPRESAI, ORDENI) returns NOTFND, or the record is not ORD-PENDIENTE",
  "action": "Set 'ORDEN NO EXISTE' if not found, or 'ORDEN NO ESTA PENDIENTE' if the status is not pending, and flag the request as in error.",
  "inputs": [
   {
    "name": "ORDENI",
    "type": "text(fixed,7,ebcdic)",
    "description": ""
   },
   {
    "name": "EMPRESAI",
    "type": "text(fixed,5,ebcdic)",
    "description": ""
   },
   {
    "name": "ORD-ESTADO",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Order not found\n Given no order 1234567 exists for company 00010\n When payment is requested\n Then the message 'ORDEN NO EXISTE' is shown",
   "Scenario: Order already paid\n Given order 1234567 exists with a status other than pending\n When payment is requested\n Then the message 'ORDEN NO ESTA PENDIENTE' is shown"
  ],
  "sources": [
   {
    "file": "cbl/PAGOORD.cbl",
    "line_start": 106,
    "line_end": 118
   }
  ]
 },
 {
  "id": "RULE-012",
  "name": "Entered amount must equal the order value",
  "category": "validation",
  "priority": "P0",
  "statement": "The entered amount VALORI is converted to a value by FUNCTION NUMVAL(VALORI) / 100 into WS-VALOR. If WS-VALOR is not equal to ORD-VALOR, the message 'VALOR NO COINCIDE CON LA ORDEN' is set in WS-MENSAJE and the HAY-ERROR flag is set.",
  "condition": "NUMVAL(VALORI)/100 <> ORD-VALOR",
  "action": "Set message 'VALOR NO COINCIDE CON LA ORDEN' and flag the request as in error.",
  "inputs": [
   {
    "name": "VALORI",
    "type": "text(fixed,11,ebcdic)",
    "description": ""
   },
   {
    "name": "ORD-VALOR",
    "type": "decimal(11,2,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-VALOR",
    "type": "decimal(11,2,signed)",
    "description": ""
   },
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   }
  ],
