                return Optional.empty();
            }

            @Override
            public int updateBalance(Long accountNumber, BigDecimal balance) {
                events.add("updateBalance");
                balanceUpdates.add(new Object[] {accountNumber, balance});
                return 1;
            }
        };

        final MovementGateway movements = orderNumber -> {
            events.add("registerMovement");
            movementCalls.add(orderNumber);
            return movementNumber;
        };

        PayOrderService service() {
            return new PayOrderService(orders, accounts, movements);
        }
    }

    private static PayOrderRequest request(String orderNumber, String companyId, String accountType,
            String accountNumber, String amount, String channel, String key) {
        return new PayOrderRequest(orderNumber, companyId, accountType, accountNumber,
                new BigDecimal(amount), channel, key);
    }

